#!/usr/bin/env python3
"""Apply one task-based delegation policy to native Codex and Claude settings."""
import argparse
import base64
import datetime
import hashlib
import json
import os
from pathlib import Path
import re
import stat
import sys
import tempfile
import tomllib

ROLES = {
    "scan": "Read and extract facts. Do not edit files.",
    "work": "Handle routine implementation and focused tests. Escalate difficult or uncertain work to the expert model.",
    "review": "Advise on planning, difficult decisions and correctness. Also implement difficult changes when delegated; for advice-only tasks, return guidance without editing.",
}
WORKER_CONTEXT = (
    "Work from the delegation brief and applicable project instructions; do not assume you can see the parent's conversation or previously read files. "
    "Read the relevant source material before deciding. If a missing requirement or decision could change the outcome, ask the parent for it before taking the dependent action; continue independent work. "
    "Return findings or changes with file references, checks performed and unresolved assumptions. Advice should distinguish observed facts from inferences."
)
MARKER = "Generated by t3-delegation; edit policy.json and run apply."
START = "<!-- t3-delegation:begin -->"
END = "<!-- t3-delegation:end -->"
EFFORTS = {"codex": {"none", "minimal", "low", "medium", "high", "xhigh", "max", "ultra"},
           "claude": {"low", "medium", "high", "xhigh", "max"}}


def fail(message):
    raise ValueError(message)


def shape(value, keys, label):
    if not isinstance(value, dict) or set(value) != set(keys):
        fail(f"{label}: expected exactly {', '.join(keys)}")


def string(value, label, nullable=False):
    if nullable and value is None:
        return
    if (not isinstance(value, str) or not value.strip() or value != value.strip() or len(value) > 256
            or any(ord(c) < 32 or ord(c) == 127 or 0xD800 <= ord(c) <= 0xDFFF for c in value)):
        fail(f"{label}: expected a nonempty string without control characters or edge whitespace (max 256 characters)")


def validate(policy):
    shape(policy, ("version", "codex", "claude"), "policy")
    if type(policy["version"]) is not int or policy["version"] != 1:
        fail("policy.version must be 1")
    for provider in ("codex", "claude"):
        settings = policy[provider]
        keys = ("default_role", "roles") + (("advisor_model",) if provider == "claude" else ())
        shape(settings, keys, provider)
        if not isinstance(settings["default_role"], str) or settings["default_role"] not in ROLES:
            fail(f"{provider}.default_role must be scan, work or review")
        shape(settings["roles"], ROLES, f"{provider}.roles")
        for role, values in settings["roles"].items():
            shape(values, ("model", "effort"), f"{provider}.{role}")
            string(values["model"], f"{provider}.{role}.model")
            string(values["effort"], f"{provider}.{role}.effort", nullable=True)
            if values["effort"] is not None and values["effort"] not in EFFORTS[provider]:
                fail(f"{provider}.{role}.effort: expected one of {', '.join(sorted(EFFORTS[provider]))} or null")
        if provider == "claude":
            string(settings["advisor_model"], "claude.advisor_model", nullable=True)
    return policy


def quoted(value):
    # JSON double quotes are valid TOML/YAML scalars; escape YAML's extra line breaks.
    return (json.dumps(value, ensure_ascii=False).replace("\u0085", "\\u0085")
            .replace("\u2028", "\\u2028").replace("\u2029", "\\u2029"))


def safe_path(path):
    path = Path(path).absolute()
    for part in (path, *path.parents):
        if part.is_symlink():
            fail(f"Refusing symlink: {part}")
    return path


def snapshot(path):
    safe_path(path)
    try:
        info = path.stat()
    except FileNotFoundError:
        return None
    if not stat.S_ISREG(info.st_mode):
        fail(f"Expected a regular file: {path}")
    return (path.read_bytes(), stat.S_IMODE(info.st_mode), info.st_ino, info.st_mtime_ns)


def digest(data):
    return hashlib.sha256(data).hexdigest()


def atomic_write(path, data, mode=0o600):
    safe_path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, temporary = tempfile.mkstemp(prefix=".t3-delegation-", dir=path.parent)
    try:
        with os.fdopen(fd, "wb") as stream:
            os.fchmod(stream.fileno(), mode)
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)


def managed_block(text, block, path):
    if text.count(START) != text.count(END) or text.count(START) > 1:
        fail(f"Unbalanced or repeated delegation markers: {path}")
    if START in text:
        before, rest = text.split(START)
        if END in before:
            fail(f"Reversed delegation markers: {path}")
        _, after = rest.split(END)
        return before + block + after
    return text + ("\n\n" if text and not text.endswith("\n\n") else "") + block + "\n"


def instructions(provider, settings):
    lines = [START, "The user explicitly authorizes task-based model delegation under this policy.",
             "Choose models by task difficulty, uncertainty and risk, not just task category. The parent retains judgment and integrates their results.",
             "Use the work model for well-understood implementation; use the review model for difficult implementation as well as advice. Large models are not restricted to reviewing others' code.",
             "Use the review model as an advisor for substantial planning, architectural choices, persistent failures and consequential checks. Give it a focused question; let the work model execute a clear plan when suitable.",
             "If implementation itself needs deeper reasoning, delegate it directly to the review model instead of repeatedly retrying with a smaller worker. A parent already using the expert model can handle it directly.",
             "Skip workers for tiny tasks. Prefer fresh focused workers when cheaper than sharing full history.",
             "Give each fresh agent a self-contained brief: the goal, relevant user requirements and decisions, scope and edit ownership, repository/worktree and file paths, evidence and known failures, and success criteria. Include only what the task needs, but do not omit constraints to save tokens.",
             "For expert advice, include the decision to make, plausible alternatives and uncertainties; for implementation, include expected behavior, interfaces and validation. Point agents to source material rather than relying only on a summary, and explicitly pass relevant skill instructions or references.",
             "Workers must flag missing context instead of guessing. Relay later user corrections and decisions to affected running agents; their context does not automatically stay in sync. Check their evidence and assumptions before integrating results.",
             "Measure memory headroom before fan-out and cap concurrency to that headroom.",
             "Report unavailable models; never claim a requested model ran without evidence."]
    for role, values in settings["roles"].items():
        effort = values["effort"] if values["effort"] is not None else "no explicit override (native defaults/inheritance)"
        lines.append(f"- t3-{role}: model {json.dumps(values['model'])}, effort {json.dumps(effort)}. {ROLES[role]}")
    if provider == "codex":
        lines += ["Use native named roles. If custom roles are unavailable, spawn with the explicit model and reasoning effort and fork_turns=\"none\". A null effort means omit the effort override.",
                  "Never override the parent model. Use a full-history fork only when essential."]
    else:
        lines += ["Use native named agents or an explicit model and effort. A null effort means omit the effort override. Avoid full-history forks for routine work.",
                  "When the native advisor is available, prefer it for a focused consultation; use the expert agent for independent investigation or difficult implementation. Do not request both for the same question without a reason.",
                  "The native advisor receives the calling conversation, not an automatic view of the whole repository or other agents' conversations. Bring relevant evidence and requirements into that conversation before consulting it; a worker's advisor sees that worker's context.",
                  "Never override the parent model. Model aliases can resolve to the current provider version."]
    return "\n".join(lines + [END])


def toml_tables(text):
    """Find table headers outside strings, including multiline TOML strings."""
    quote = None
    for number, line in enumerate(text.splitlines(keepends=True)):
        if quote is None and re.match(r"\s*\[", line):
            try:
                table = tomllib.loads(line + "\n__t3_probe = 0\n")
                keys = []
                while isinstance(table, dict) and "__t3_probe" not in table and len(table) == 1:
                    key, table = next(iter(table.items()))
                    keys.append(key)
                yield number, tuple(keys) if isinstance(table, dict) and "__t3_probe" in table else None
            except tomllib.TOMLDecodeError:
                pass
        i = 0
        while i < len(line):
            if quote:
                if quote.startswith('"') and line[i] == "\\":
                    i += 2
                    continue
                if line.startswith(quote, i):
                    i += len(quote)
                    quote = None
                    continue
            else:
                if line[i] == "#":
                    break
                if line[i] in "\"'":
                    quote = line[i] * (3 if line.startswith(line[i] * 3, i) else 1)
                    i += len(quote)
                    continue
            i += 1


def codex_config(text, values):
    parsed = tomllib.loads(text)
    if "agents" in parsed and not isinstance(parsed["agents"], dict):
        fail("Codex agents must be a TOML table")
    lines = text.splitlines(keepends=True)
    headers = list(toml_tables(text))
    agents = next((i for i, keys in headers if keys == ("agents",)), None)
    desired = {"default_subagent_model": values["model"],
               "default_subagent_reasoning_effort": values["effort"]}
    additions = "".join(f"{key} = {quoted(value)}\n"
                        for key, value in desired.items() if value is not None)
    if agents is None:
        # An inline agents table cannot be expanded surgically without rewriting its contents.
        if "agents" in parsed and not any(keys and keys[0] == "agents" for _, keys in headers):
            fail("Codex inline agents table must be expanded to [agents] before applying")
        result = text + ("\n" if text and not text.endswith("\n") else "") + "\n[agents]\n" + additions
    else:
        stop = next((i for i, _ in headers if i > agents), len(lines))
        kept = []
        i = agents + 1
        while i < stop:
            line = lines[i]
            key = None
            if "=" in line:
                try:
                    lhs = tomllib.loads(line.split("=", 1)[0] + "= 0")
                    if len(lhs) == 1:
                        key = next(iter(lhs))
                except tomllib.TOMLDecodeError:
                    pass
            end = i + 1
            if key is not None:
                while True:
                    try:
                        tomllib.loads("".join(lines[i:end]))
                        break
                    except tomllib.TOMLDecodeError:
                        end += 1
                        if end > stop:
                            fail("Cannot safely locate Codex delegation option")
            if key not in desired:
                kept.extend(lines[i:end])
            i = end
        result = "".join(lines[:agents + 1]) + additions + "".join(kept) + "".join(lines[stop:])
    updated = tomllib.loads(result)
    expected = dict(parsed)
    expected["agents"] = dict(parsed.get("agents", {}))
    for key, value in desired.items():
        expected["agents"].pop(key, None)
        if value is not None:
            expected["agents"][key] = value
    if updated != expected:
        fail("Codex TOML edit would change unrelated settings")
    return result


def plan(policy, codex_home, claude_home):
    changes = {}
    def add(path, render):
        path = safe_path(path)
        old = snapshot(path)
        text = old[0].decode("utf-8") if old else ""
        new = render(text).encode("utf-8")
        if old is None or new != old[0]:
            if path in changes:
                fail(f"Overlapping provider paths: {path}")
            changes[path] = (old, new)
    for provider, home in (("codex", codex_home), ("claude", claude_home)):
        settings = policy[provider]
        for role, values in settings["roles"].items():
            name = f"t3-{role}"
            if provider == "codex":
                fields = {"name": name, "description": ROLES[role], "model": values["model"],
                          "developer_instructions": ROLES[role] + "\n\n" + WORKER_CONTEXT}
                if values["effort"] is not None:
                    fields["model_reasoning_effort"] = values["effort"]
                content = f"# {MARKER}\n" + "".join(f"{key} = {quoted(value)}\n" for key, value in fields.items())
                tomllib.loads(content)
                path = home / "agents" / f"{name}.toml"
            else:
                fields = {"name": name, "description": ROLES[role], "model": values["model"]}
                if values["effort"] is not None:
                    fields["effort"] = values["effort"]
                content = "---\n" + "".join(f"{key}: {quoted(value)}\n" for key, value in fields.items())
                content += f"---\n<!-- {MARKER} -->\n\n{ROLES[role]}\n\n{WORKER_CONTEXT}\n"
                path = home / "agents" / f"{name}.md"
            def agent(text, content=content, path=path):
                if path.exists() and MARKER not in text:
                    fail(f"Refusing to overwrite unmanaged agent: {path}")
                return content
            add(path, agent)
        filename = "AGENTS.md" if provider == "codex" else "CLAUDE.md"
        add(home / filename, lambda text, p=provider, s=settings, path=home / filename:
            managed_block(text, instructions(p, s), path))
    default = policy["codex"]["roles"][policy["codex"]["default_role"]]
    add(codex_home / "config.toml", lambda text: codex_config(text, default))
    def claude_config(text):
        settings = json.loads(text) if text.strip() else {}
        if not isinstance(settings, dict) or not isinstance(settings.get("env", {}), dict):
            fail("Claude settings and env must be JSON objects")
        env = settings.setdefault("env", {})
        if str(env.get("CLAUDE_CODE_SUBAGENT_MODEL_FORCE", "")).lower() in ("true", "1"):
            fail("CLAUDE_CODE_SUBAGENT_MODEL_FORCE conflicts with task-based routing; remove it explicitly")
        env["CLAUDE_CODE_SUBAGENT_MODEL"] = policy["claude"]["roles"][policy["claude"]["default_role"]]["model"]
        settings.pop("advisorModel", None)
        if policy["claude"]["advisor_model"] is not None:
            settings["advisorModel"] = policy["claude"]["advisor_model"]
        return json.dumps(settings, indent=2, ensure_ascii=False) + "\n"
    add(claude_home / "settings.json", claude_config)
    return changes


def unchanged(changes):
    for path, (before, _) in changes.items():
        if snapshot(path) != before:
            fail(f"File changed after preflight: {path}")


def transact(changes, modes=None):
    unchanged(changes)
    written = []
    try:
        for path, (before, after) in changes.items():
            unchanged({path: (before, after)})
            if after is None:
                path.unlink()
            else:
                mode = modes[path] if modes and path in modes else before[1] if before else 0o600
                atomic_write(path, after, mode)
            written.append(path)
    except BaseException:
        for path in reversed(written):
            before, after = changes[path]
            current = snapshot(path)
            if (current[0] if current else None) != after:
                fail(f"Rollback stopped because a file changed: {path}")
            if before is None:
                path.unlink()
            else:
                atomic_write(path, before[0], before[1])
        raise


def apply(changes, config):
    if not changes:
        print("Already applied; no files changed.")
        return
    unchanged(changes)
    root = safe_path(config.parent / "backups")
    root.mkdir(parents=True, exist_ok=True, mode=0o700)
    backup = Path(tempfile.mkdtemp(prefix=datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%dT%H%M%S-"), dir=root))
    entries = []
    for path, (before, after) in changes.items():
        entries.append({"path": str(path), "before": base64.b64encode(before[0]).decode() if before else None,
                        "mode": before[1] if before else None, "after_sha256": digest(after)})
    atomic_write(backup / "manifest.json", (json.dumps({"version": 1, "files": entries}, indent=2) + "\n").encode())
    transact(changes)
    print(f"Applied {len(changes)} files. Backup: {backup}")


def restore(backup):
    manifest = json.loads(safe_path(backup / "manifest.json").read_text())
    shape(manifest, ("version", "files"), "backup")
    if manifest["version"] != 1 or not isinstance(manifest["files"], list):
        fail("Unsupported backup manifest")
    changes, modes = {}, {}
    for entry in manifest["files"]:
        shape(entry, ("path", "before", "mode", "after_sha256"), "backup entry")
        path = safe_path(entry["path"])
        current = snapshot(path)
        if current is None or digest(current[0]) != entry["after_sha256"]:
            fail(f"Restore refused: file changed since apply: {path}")
        if path in changes:
            fail("Duplicate path in backup")
        previous = base64.b64decode(entry["before"], validate=True) if entry["before"] is not None else None
        mode = entry["mode"]
        if previous is not None and (type(mode) is not int or not 0 <= mode <= 0o7777):
            fail("Invalid file mode in backup")
        changes[path] = (current, previous)
        modes[path] = mode
    transact(changes, modes)
    print(f"Restored {len(changes)} files.")


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--config", type=Path, default=Path.home() / ".config/t3-delegation/policy.json")
    parser.add_argument("--codex-home", type=Path, default=Path(os.environ.get("CODEX_HOME", str(Path.home() / ".codex"))))
    parser.add_argument("--claude-home", type=Path, default=Path(os.environ.get("CLAUDE_CONFIG_DIR", str(Path.home() / ".claude"))))
    commands = parser.add_subparsers(dest="command", required=True)
    commands.add_parser("apply").add_argument("--dry-run", action="store_true")
    commands.add_parser("check")
    commands.add_parser("show")
    commands.add_parser("restore").add_argument("backup", type=Path)
    args = parser.parse_args(argv)
    try:
        if args.command == "restore":
            restore(args.backup)
            return 0
        policy = validate(json.loads(safe_path(args.config).read_text()))
        for provider in ("codex", "claude"):
            print(f"{provider}: default role {policy[provider]['default_role']}")
            for role, values in policy[provider]["roles"].items():
                print(f"  {role}: {json.dumps(values['model'])}, effort {json.dumps(values['effort'])}")
            if provider == "claude":
                print(f"  advisor: {json.dumps(policy[provider]['advisor_model'])}")
        if args.command == "show":
            return 0
        changes = plan(policy, args.codex_home, args.claude_home)
        for path in changes:
            print(f"Pending: {path}")
        if args.command == "apply" and not args.dry_run:
            apply(changes, args.config)
        else:
            print(f"Validated; {len(changes)} pending files.")
        return 0
    except (ValueError, OSError, TypeError, UnicodeError) as error:
        print(f"t3-delegation: {error}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main())
